import os, stat

def walk_files_new(start_path_original, opts):
    start_abs = os.path.abspath(start_path_original)
    if os.path.isfile(start_abs):
        yield (start_abs, start_path_original)
        return
    max_depth = opts['depth']
    if max_depth == -1:
        max_depth = float('inf')
    stack = [(start_abs, 0, start_path_original)]
    while stack:
        cur_abs, cur_depth, orig_prefix = stack.pop()
        if cur_depth > max_depth:
            continue
        try:
            entries = os.listdir(cur_abs)
        except:
            continue
        for entry in entries:
            full_abs = os.path.join(cur_abs, entry)
            # rel to cur_abs
            rel = os.path.relpath(full_abs, cur_abs)
            # display join
            if orig_prefix == '.':
                # if orig is '.', display is rel plus any subdirs already in cur_abs relative to start?
                # Actually for cur_abs = start_abs, rel = entry, display = entry (since orig is '.')
                # For cur_abs = start_abs/sub, orig_prefix = sub, rel = c.txt, display = sub/c.txt
                # So we need to compute display as os.path.join(orig_prefix, rel) unless orig_prefix == '.'
                # For orig_prefix == '.', we want display = os.path.relpath(full_abs, start_abs) ? Let's compute
                # For cur_abs = start_abs/sub, orig_prefix = sub, full_abs = start_abs/sub/c.txt
                # rel to cur_abs = c.txt, display = sub/c.txt (good)
                # For cur_abs = start_abs, orig_prefix = '.', entry = a.txt, rel = a.txt, display should be a.txt (not ./a.txt)
                # So if orig_prefix == '.', display = os.path.relpath(full_abs, start_abs) (which is a.txt or sub/c.txt)
                # Actually for cur_abs = start_abs/sub, orig_prefix = sub, full_abs = start_abs/sub/c.txt, rel to cur_abs = c.txt, but we want display = sub/c.txt, which is os.path.join(orig_prefix, rel) = sub/c.txt, but also os.path.relpath(full_abs, start_abs) = sub/c.txt, so both give same when orig_prefix is sub and cur_abs is start_abs/sub.
                # For cur_abs = start_abs, orig_prefix = '.', entry = sub (dir), full_abs = start_abs/sub, rel to cur_abs = sub, display should be sub (not ./sub)
                # So if orig_prefix == '.', display = os.path.relpath(full_abs, start_abs)
                if orig_prefix == '.':
